SELECT sum(TraceCount) AS traces, sum(CostSum) AS cost
FROM trace_metrics_by_minute
WHERE BucketStart >= {dashboard_context_period_start:DateTime} AND BucketStart < {dashboard_context_period_end:DateTime}

SELECT bucket, sum(came_in) AS came_in, sum(reviewed) AS reviewed
FROM (
  SELECT addSeconds(toStartOfInterval(subtractSeconds(CreatedAt, 345600), INTERVAL {dashboard_context_granularity_seconds:UInt32} SECOND), 345600) AS bucket, 1 AS came_in, 0 AS reviewed
  FROM annotation_queue_items
  WHERE CreatedAt >= {dashboard_context_period_start:DateTime} AND CreatedAt < {dashboard_context_period_end:DateTime}
  UNION ALL
  SELECT addSeconds(toStartOfInterval(subtractSeconds(DoneAt, 345600), INTERVAL {dashboard_context_granularity_seconds:UInt32} SECOND), 345600) AS bucket, 0 AS came_in, 1 AS reviewed
  FROM annotation_queue_items
  WHERE CreatedAt < {dashboard_context_period_end:DateTime}
    AND DoneAt >= {dashboard_context_period_start:DateTime} AND DoneAt < {dashboard_context_period_end:DateTime}
)
GROUP BY bucket
ORDER BY bucket
